CREATE OR REPLACE FUNCTION public.finalize_gateway_unknown_attempt(p_transaction_id uuid,p_user_id uuid,p_status text,p_external_id text DEFAULT NULL,p_failure_code text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_tx public.gateway_transactions%ROWTYPE; v_ext text:=NULLIF(trim(coalesce(p_external_id,'')),''); BEGIN IF p_status NOT IN ('approved','pending','declined','failed') THEN RAISE EXCEPTION 'invalid_recovery_status'; END IF; SELECT * INTO v_tx FROM public.gateway_transactions WHERE id=p_transaction_id AND user_id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'transaction_not_found'; END IF; IF p_status='approved' AND v_ext IS NULL THEN RAISE EXCEPTION 'gateway_external_id_required_for_terminal_state'; END IF; IF v_tx.status IN ('approved','refunded','chargeback') THEN RETURN jsonb_build_object('status',v_tx.status,'changed',false,'transaction_id',v_tx.id); END IF; IF v_tx.status='declined' AND p_status='approved' THEN RAISE EXCEPTION 'terminal_decline_cannot_be_recovered'; END IF; UPDATE public.gateway_transactions SET status=p_status,external_id=coalesce(v_ext,external_id),failure_code=coalesce(NULLIF(trim(coalesce(p_failure_code,'')),''),failure_code),updated_at=now(),version=coalesce(version,0)+1,completed_at=CASE WHEN p_status IN ('approved','declined','failed') THEN coalesce(completed_at,now()) ELSE completed_at END WHERE id=v_tx.id AND user_id=p_user_id; RETURN jsonb_build_object('status',p_status,'changed',true,'transaction_id',v_tx.id); END; $$; REVOKE EXECUTE ON FUNCTION public.finalize_gateway_unknown_attempt(uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finalize_gateway_unknown_attempt(uuid,uuid,text,text,text) TO service_role;